-- Passage rg7-literary-structure-pov-p02
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('87aa5ec6-ebf2-5a87-b76e-6e1b04448789', 'rg7-literary-structure-pov-p02', (select id from public.skills where slug = 'read-g7-literary-structure-pov'), null,
        '6-8', $q$Scales$q$, $q$On Monday, the notes trip over each other,
my fingers as clumsy as boots on ice.
Up the keys and down again.
Up the keys and down again.

On Tuesday, my brother bangs on the wall.
The cat leaves the room on purpose.
Up the keys and down again.
Up the keys and down again.

On Wednesday, the metronome ticks like a judge,
and I lose the race by half a beat.
Up the keys and down again.
Up the keys and down again.

On Thursday, I play with my eyes closed
and hear one scale come out smooth,
clean as water poured into a glass.
Up the keys, and down, and again.

On Friday, my brother stops banging.
The cat curls up beside the bench.
I climb the keys like stairs I know by heart,
and I do not need to count the steps.
The music simply carries me
all the way up and safely home.$q$, 'draft')
