-- Passage rg7-literary-structure-pov-p05
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('4bc3369d-db84-55bf-aff4-d38787677868', 'rg7-literary-structure-pov-p05', (select id from public.skills where slug = 'read-g7-literary-structure-pov'), null,
        '6-8', $q$Lunch Tray, Two Voices$q$, $q$FIRST VOICE (Amara, new at Hillcrest Middle):
The hallway is a river,
and I am a leaf floating the wrong way.
Everyone knows where the cafeteria is.
Everyone knows everyone.

SECOND VOICE (Jun, in his second year):
The hallway is a river,
and I swim it without thinking.
I know where the cafeteria is.
I know every name, but no one sits with me.

FIRST VOICE:
I hold my lunch tray like a shield
and search the room for one empty seat.
The noise rises like a wave.

SECOND VOICE:
I save the seat beside me every day,
though no one ever asks for it.
I eat slowly, just in case.

FIRST VOICE:
There is a boy alone by the window.

SECOND VOICE:
There is a girl standing still with her tray.

FIRST VOICE:
I take one step.

SECOND VOICE:
I look up.

BOTH VOICES:
Is this seat taken?
No. I was saving it for you.$q$, 'draft')
